    // ------------------------------------------------------------------------
    $this->start_controls_section(
      'table_of_contents_indicator_styles_section',
        [
          'label' => esc_html__( 'Scroll Indicator', 'themeasy-lite' ),
          'tab' => Controls_Manager::TAB_STYLE,
        ]
      );

      $this->add_control(
        'track_color',
        [
          'label' => esc_html__( 'Rail Track Color', 'themeasy-lite' ),
          'description' => esc_html__( 'The thin vertical line the indicator slides on.', 'themeasy-lite' ),
          'type' => Controls_Manager::COLOR,
          'selectors' => [
            '{{WRAPPER}} .tms-table-of-contents' => '--tms-table-of-contents-track-color: {{VALUE}};',
          ],
        ]
      );

      $this->add_control(
        'indicator_color',
        [
          'label' => esc_html__( 'Indicator Color', 'themeasy-lite' ),
          'type' => Controls_Manager::COLOR,
          'selectors' => [
            '{{WRAPPER}} .tms-table-of-contents' => '--tms-table-of-contents-indicator-color: {{VALUE}};',
          ],
          'condition' => [
            'highlight_on_scroll' => 'yes',
          ],
        ]
      );

      $this->add_control(
        'indicator_width',
        [
          'label' => esc_html__( 'Rail Width', 'themeasy-lite' ),
          'type' => Controls_Manager::SLIDER,
          'size_units' => ['px'],
          'range' => [
            'px' => [
              'min' => 1,
              'max' => 6,
              'step' => 0.5,
            ],
          ],
          'selectors' => [
            '{{WRAPPER}} .tms-table-of-contents' => '--tms-table-of-contents-indicator-width: {{SIZE}}{{UNIT}};',
          ],
        ]
      );

      // Reading progress line.
      $this->add_control(
        'progress_heading',
        [
          'label' => esc_html__( 'Reading Progress', 'themeasy-lite' ),
          'type' => Controls_Manager::HEADING,
          'separator' => 'before',
          'condition' => [
            'reading_progress' => 'yes',
          ],
        ]
      );

      $this->add_control(
        'progress_color',
        [
          'label' => esc_html__( 'Fill Color', 'themeasy-lite' ),
          'type' => Controls_Manager::COLOR,
          'selectors' => [
            '{{WRAPPER}} .tms-table-of-contents' => '--tms-table-of-contents-progress-color: {{VALUE}};',
          ],
          'condition' => [
            'reading_progress' => 'yes',
          ],
        ]
      );

      $this->add_control(
        'progress_thickness',
        [
          'label' => esc_html__( 'Thickness', 'themeasy-lite' ),
          'type' => Controls_Manager::SLIDER,
          'size_units' => ['px'],
          'range' => [
            'px' => [
              'min' => 1,
              'max' => 6,
              'step' => 0.5,
            ],
          ],
          'selectors' => [
            '{{WRAPPER}} .tms-table-of-contents' => '--tms-table-of-contents-progress-thickness: {{SIZE}}{{UNIT}};',
          ],
          'condition' => [
            'reading_progress' => 'yes',
          ],
        ]
      );

    $this->end_controls_section();

  }

  /**
   * Render the widget output on the frontend.
   *
   * @return void
   */
  protected function render() {
    $settings = $this->get_settings_for_display();

    // ------------------------------------------------------------------------
    // Settings.
    // ------------------------------------------------------------------------
    $title_text = $settings['title_text'] ?? '';
    $title_icon = is_array( $settings['title_icon'] ?? null ) ? $settings['title_icon'] : [];

    $title_tag = themeasy_sanitize_heading_tag(
      $settings['title_html_tag'] ?? 'h4',
      'h4',
      ['h2', 'h3', 'h4', 'h5', 'h6', 'p', 'div', 'span']
    );

    $allowed_levels = ['h2', 'h3', 'h4', 'h5', 'h6'];
    $levels = array_values( array_intersect(
      $allowed_levels,
      array_map( 'strval', is_array( $settings['heading_levels'] ?? null ) ? $settings['heading_levels'] : [] )
    ) );

    if ( empty( $levels ) ) {
      $levels = ['h2', 'h3'];
    }

    $source = 'custom' === ( $settings['content_source'] ?? 'page' ) ? 'custom' : 'page';
    $content_selector = 'custom' === $source ? trim( (string) ( $settings['content_selector'] ?? '' ) ) : '';
    $exclude_selector = trim( (string) ( $settings['exclude_selector'] ?? '' ) );

    $min_headings = (int) ( $settings['min_headings'] ?? 0 );

    if ( $min_headings < 1 ) {
      $min_headings = 2;
    }

    $show_hierarchy = 'yes' === ( $settings['show_hierarchy'] ?? '' );

    $list_marker = in_array( $settings['list_marker'] ?? 'none', ['numbers', 'bullets'], true )
      ? $settings['list_marker']
      : 'none';

    $highlight = 'yes' === ( $settings['highlight_on_scroll'] ?? '' );
    $progress = 'yes' === ( $settings['reading_progress'] ?? '' );
    $smooth = 'yes' === ( $settings['smooth_scroll'] ?? '' );

    // Scroll offset is responsive; tablet/mobile stay empty when unset so the
    // JS inherits the next-wider value (Elementor's own responsive model).
    $scroll_offset = max( 0, (int) ( $settings['scroll_offset']['size'] ?? 32 ) );
    $scroll_offset_tablet = $settings['scroll_offset_tablet']['size'] ?? '';
    $scroll_offset_mobile = $settings['scroll_offset_mobile']['size'] ?? '';

    $collapsible = 'yes' === ( $settings['collapsible'] ?? '' );

    $collapsed_on_load = in_array( $settings['collapsed_on_load'] ?? 'never', ['mobile', 'always'], true )
      ? $settings['collapsed_on_load']
      : 'never';

    // ------------------------------------------------------------------------
    // Wrapper classes + attributes.
    // ------------------------------------------------------------------------
    $wrapper_classes = ['tms-table-of-contents'];
    $wrapper_atts = [];

    if ( 'none' !== $list_marker ) {
      $wrapper_classes[] = 'tms-table-of-contents--' . $list_marker;
    }

    if ( $highlight ) {
      $wrapper_classes[] = 'tms-table-of-contents--spy';
    }

    if ( $collapsible ) {
      $wrapper_classes[] = 'tms-table-of-contents--collapsible';
    }

    if ( themeasy_is_elementor_editor() ) {
      $wrapper_classes[] = 'tms-table-of-contents--static';
    }

    // Landmark label for assistive tech.
    $wrapper_atts['aria-label'] = '' !== $title_text ? $title_text : __( 'Table of contents', 'themeasy-lite' );

    // Scan + behavior config consumed by the JS module (truthy strings only —
    // themeasy_html_attributes() drops empty values by design).
    $wrapper_atts['data-levels'] = implode( ',', $levels );
    $wrapper_atts['data-selector'] = $content_selector;
    $wrapper_atts['data-exclude'] = $exclude_selector;
    $wrapper_atts['data-min'] = (string) $min_headings;
    $wrapper_atts['data-nested'] = $show_hierarchy ? 'true' : '';
    $wrapper_atts['data-smooth'] = $smooth ? 'true' : '';
    $wrapper_atts['data-offset'] = (string) $scroll_offset;
    $wrapper_atts['data-offset-tablet'] = is_numeric( $scroll_offset_tablet ) ? (string) max( 0, (int) $scroll_offset_tablet ) : '';
    $wrapper_atts['data-offset-mobile'] = is_numeric( $scroll_offset_mobile ) ? (string) max( 0, (int) $scroll_offset_mobile ) : '';
    $wrapper_atts['data-collapsed'] = $collapsible && 'never' !== $collapsed_on_load ? $collapsed_on_load : '';

    $wrapper_classes_output = implode( ' ', array_filter( $wrapper_classes ) );

    // ------------------------------------------------------------------------
    // Header pieces.
    // ------------------------------------------------------------------------
    $icon_html = themeasy_render_icon_html( $title_icon );
    $has_header = '' !== $title_text || '' !== $icon_html || $collapsible || $progress;

    // ------------------------------------------------------------------------
    // Render attributes.
    // ------------------------------------------------------------------------
    $this->add_render_attribute( 'title_text', 'class', 'tms-table-of-contents__title' );
    $this->add_inline_editing_attributes( 'title_text', 'none' );

    // ------------------------------------------------------------------------
    // Output — the list is empty on the server; the JS module scans the page
    // and fills it (no-JS visitors get the shell with the list collapsed).
    // ------------------------------------------------------------------------
    ?>
    <nav class="<?php echo esc_attr( $wrapper_classes_output ); ?>"<?php themeasy_print_html_attributes( $wrapper_atts ); ?>>
      <div class="tms-table-of-contents__inner tms-animation__target">

        <?php if ( $has_header ) : ?>
          <div class="tms-table-of-contents__header">

            <?php if ( '' !== $title_text || '' !== $icon_html ) : ?>
              <div class="tms-table-of-contents__heading">

                <?php if ( $icon_html ) : ?>
                  <span class="tms-table-of-contents__icon" aria-hidden="true">
                    <?php echo wp_kses( $icon_html, themeasy_get_icon_kses_tags() ); ?>
                  </span>
                <?php endif; ?>

                <?php if ( '' !== $title_text ) : ?>
                  <<?php echo tag_escape( $title_tag ); ?> <?php $this->print_render_attribute_string( 'title_text' ); ?>>
                    <?php echo esc_html( $title_text ); ?>
                  </<?php echo tag_escape( $title_tag ); ?>>
                <?php endif; ?>

              </div><!-- /.tms-table-of-contents__heading -->
            <?php endif; ?>

            <?php if ( $collapsible ) : ?>
              <button type="button" class="tms-table-of-contents__toggle" aria-expanded="true" aria-label="<?php esc_attr_e( 'Toggle table of contents', 'themeasy-lite' ); ?>">
                <?php echo wp_kses( themeasy_get_svg_icon( 'ty-feather', 'chevron-down', 'tms-table-of-contents__toggle-icon' ), themeasy_get_icon_kses_tags() ); ?>
              </button>
            <?php endif; ?>

            <?php if ( $progress ) : ?>
              <span class="tms-table-of-contents__progress" aria-hidden="true"></span>
            <?php endif; ?>

          </div><!-- /.tms-table-of-contents__header -->
        <?php endif; ?>

        <div class="tms-table-of-contents__body">
          <div class="tms-table-of-contents__panel">

            <?php if ( $highlight ) : ?>
              <span class="tms-table-of-contents__marker" aria-hidden="true"></span>
            <?php endif; ?>

            <ol class="tms-table-of-contents__list"></ol>

            <span class="tms-table-of-contents__placeholder">
              <?php esc_html_e( 'No matching headings found yet — the list is built from the headings on this page.', 'themeasy-lite' ); ?>
            </span>

          </div><!-- /.tms-table-of-contents__panel -->
        </div><!-- /.tms-table-of-contents__body -->

      </div><!-- /.tms-table-of-contents__inner -->
    </nav><!-- /.tms-table-of-contents -->
    <?php
  }

  /**
   * Render the live preview template used by the Elementor editor.
   *
   * @return void
   */
  protected function content_template() {
    ?>
    <#
      // ------------------------------------------------------------------------
      // Settings.
      // ------------------------------------------------------------------------
      var titleText = settings.title_text || '';

      var allowedTitleTags = [ 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'div', 'span' ];
      var titleTag = ( allowedTitleTags.indexOf( settings.title_html_tag ) !== -1 )
        ? settings.title_html_tag
        : 'h4';

      var allowedLevels = [ 'h2', 'h3', 'h4', 'h5', 'h6' ];
      var levels = _.filter( _.map( settings.heading_levels || [], String ), function( level ) {
        return allowedLevels.indexOf( level ) !== -1;
      } );

      if ( ! levels.length ) {
        levels = [ 'h2', 'h3' ];
      }

      var source = settings.content_source === 'custom' ? 'custom' : 'page';
      var contentSelector = source === 'custom' ? ( settings.content_selector || '' ).trim() : '';
      var excludeSelector = ( settings.exclude_selector || '' ).trim();

      var minHeadings = parseInt( settings.min_headings, 10 );

      if ( ! minHeadings || minHeadings < 1 ) {
        minHeadings = 2;
      }

      var showHierarchy = settings.show_hierarchy === 'yes';

      var listMarker = ( [ 'numbers', 'bullets' ].indexOf( settings.list_marker ) !== -1 )
        ? settings.list_marker
        : 'none';

      var highlight = settings.highlight_on_scroll === 'yes';
      var progress = settings.reading_progress === 'yes';
      var smooth = settings.smooth_scroll === 'yes';
      var scrollOffset = Math.max( 0, parseInt( settings.scroll_offset && settings.scroll_offset.size, 10 ) || 0 );

      var collapsible = settings.collapsible === 'yes';

      var collapsedOnLoad = ( [ 'mobile', 'always' ].indexOf( settings.collapsed_on_load ) !== -1 )
        ? settings.collapsed_on_load
        : 'never';

      // ------------------------------------------------------------------------
      // Wrapper classes + attributes.
      // ------------------------------------------------------------------------
      var wrapperClasses = [ 'tms-table-of-contents', 'tms-table-of-contents--static' ];
      var wrapperAtts = {};

      if ( listMarker !== 'none' ) {
        wrapperClasses.push( 'tms-table-of-contents--' + listMarker );
      }

      if ( highlight ) {
        wrapperClasses.push( 'tms-table-of-contents--spy' );
      }

      if ( collapsible ) {
        wrapperClasses.push( 'tms-table-of-contents--collapsible' );
      }

      // Landmark label for assistive tech.
      wrapperAtts['aria-label'] = titleText || '<?php echo esc_js( __( 'Table of contents', 'themeasy-lite' ) ); ?>';

      // Scan + behavior config (parity with render(); the preview runtime
      // re-runs the scan against the editor document on every render).
      wrapperAtts['data-levels'] = levels.join( ',' );
      wrapperAtts['data-selector'] = contentSelector;
      wrapperAtts['data-exclude'] = excludeSelector;
      wrapperAtts['data-min'] = String( minHeadings );
      wrapperAtts['data-nested'] = showHierarchy ? 'true' : '';
      wrapperAtts['data-smooth'] = smooth ? 'true' : '';
      wrapperAtts['data-offset'] = String( scrollOffset );
      wrapperAtts['data-collapsed'] = ( collapsible && collapsedOnLoad !== 'never' ) ? collapsedOnLoad : '';

      var wrapperClassStr = wrapperClasses.filter( Boolean ).join( ' ' );

      // ------------------------------------------------------------------------
      // Header pieces.
      // ------------------------------------------------------------------------
      var iconMarkup = ( window.Themeasy && window.Themeasy.renderIconMarkup )
        ? window.Themeasy.renderIconMarkup( view, settings.title_icon, null, {} )
        : '';

      var hasHeader = !! ( titleText || iconMarkup || collapsible || progress );

      // ------------------------------------------------------------------------
      // Render attributes.
      // ------------------------------------------------------------------------
      view.addRenderAttribute( 'title_text', 'class', 'tms-table-of-contents__title' );
      view.addInlineEditingAttributes( 'title_text', 'none' );
    #>

    <nav class="{{ wrapperClassStr }}" {{{ Themeasy.htmlAttributes( wrapperAtts ) }}}>
      <div class="tms-table-of-contents__inner tms-animation__target">

        <# if ( hasHeader ) { #>
          <div class="tms-table-of-contents__header">

            <# if ( titleText || iconMarkup ) { #>
              <div class="tms-table-of-contents__heading">

                <# if ( iconMarkup ) { #>
                  <span class="tms-table-of-contents__icon" aria-hidden="true">{{{ iconMarkup }}}</span>
                <# } #>

                <# if ( titleText ) { #>
                  <{{{ titleTag }}} {{{ view.getRenderAttributeString( 'title_text' ) }}}>
                    {{ titleText }}
                  </{{{ titleTag }}}>
                <# } #>

              </div><!-- /.tms-table-of-contents__heading -->
            <# } #>

            <# if ( collapsible ) { #>
              <button type="button" class="tms-table-of-contents__toggle" aria-expanded="true" aria-label="<?php esc_attr_e( 'Toggle table of contents', 'themeasy-lite' ); ?>">
                <?php echo wp_kses( themeasy_get_svg_icon( 'ty-feather', 'chevron-down', 'tms-table-of-contents__toggle-icon' ), themeasy_get_icon_kses_tags() ); ?>
              </button>
            <# } #>

            <# if ( progress ) { #>
              <span class="tms-table-of-contents__progress" aria-hidden="true"></span>
            <# } #>

          </div><!-- /.tms-table-of-contents__header -->
        <# } #>

        <div class="tms-table-of-contents__body">
          <div class="tms-table-of-contents__panel">

            <# if ( highlight ) { #>
              <span class="tms-table-of-contents__marker" aria-hidden="true"></span>
            <# } #>

            <ol class="tms-table-of-contents__list"></ol>

            <span class="tms-table-of-contents__placeholder">
              <?php esc_html_e( 'No matching headings found yet — the list is built from the headings on this page.', 'themeasy-lite' ); ?>
            </span>

          </div><!-- /.tms-table-of-contents__panel -->
        </div><!-- /.tms-table-of-contents__body -->

      </div><!-- /.tms-table-of-contents__inner -->
    </nav><!-- /.tms-table-of-contents -->

    <?php
  }
}
